/* From Uiverse.io by fanishah - Tags: loader */
.__UIV_SCOPE__ .container {
  width: 200px;
  height: 200px;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%);
  position: absolute;
}

.__UIV_SCOPE__ .container div {
  width: 100px;
  height: 100px;
  top: 50px;
  left: 50px;
  display: block;
  position: absolute;
}

.__UIV_SCOPE__ .top-left {
  animation: tl 7.5s ease infinite
}

.__UIV_SCOPE__ .top-right {
  animation: tr 7.5s ease infinite
}

.__UIV_SCOPE__ .bottom-left {
  animation: bl 7.5s ease infinite
}

.__UIV_SCOPE__ .bottom-right {
  animation: br 7.5s ease infinite
}

.__UIV_SCOPE__ .container div:before,
.__UIV_SCOPE__ .container div:after {
  display: block;
  position: absolute;
  content: ""
}

.__UIV_SCOPE__ .container div:before {
  width: 50px;
  height: 50px
}

.__UIV_SCOPE__ .top-left:before {
  background: rgb(251, 189, 4);
  top: 0;
  left: 0;
  border-radius: 100% 0 0 0
}

.__UIV_SCOPE__ .top-right:before {
  background: rgb(234, 67, 52);
  top: 0;
  right: 0;
  border-radius: 0 100% 0 0
}

.__UIV_SCOPE__ .bottom-left:before {
  background: rgb(52, 168, 83);
  bottom: 0;
  left: 0;
  border-radius: 0 0 0 100%
}

.__UIV_SCOPE__ .bottom-right:before {
  background: rgb(67, 135, 244);
  bottom: 0;
  right: 0;
  border-radius: 0 0 100% 0
}

.__UIV_SCOPE__ .container div:after {
  background: rgb(33, 33, 33);
  width: 25px;
  height: 25px;
  z-index: 1
}

.__UIV_SCOPE__ .top-left:after {
  top: 25px;
  left: 25px;
  border-radius: 100% 0 0 0
}

.__UIV_SCOPE__ .top-right:after {
  top: 25px;
  right: 25px;
  border-radius: 0 100% 0 0
}

.__UIV_SCOPE__ .bottom-left:after {
  bottom: 25px;
  left: 25px;
  border-radius: 0 0 0 100%
}

.__UIV_SCOPE__ .bottom-right:after {
  bottom: 25px;
  right: 25px;
  border-radius: 0 0 100% 0
}

@keyframes tl {
  0%,96%,100% {
    transform: rotate(0deg)
  }

  12% {
    transform: rotate(-45deg)
  }

  24% {
    transform: rotate(-90deg)
  }

  36% {
    transform: rotate(-135deg)
  }

  48% {
    left: 50px;
    transform: rotate(-180deg)
  }

  60% {
    left: 125px;
    opacity: 1;
    transform: rotate(-135deg)
  }

  61%,95% {
    opacity: 0
  }
}

@keyframes tr {
  0% {
    transform: rotate(0deg)
  }

  12% {
    transform: rotate(-45deg)
  }

  24% {
    transform: rotate(-90deg)
  }

  36% {
    transform: rotate(-135deg)
  }

  48% {
    transform: rotate(-180deg)
  }

  60% {
    transform: rotate(-225deg)
  }

  72% {
    transform: rotate(-270deg)
  }

  84% {
    transform: rotate(-315deg)
  }

  96%,100% {
    transform: rotate(-360deg)
  }
}

@keyframes bl {
  0%,100% {
    transform: rotate(0deg)
  }

  12% {
    transform: rotate(-45deg)
  }

  24% {
    left: 50px;
    transform: rotate(-90deg)
  }

  36% {
    left: 125px;
    opacity: 1;
    transform: rotate(-45deg)
  }

  37%,83% {
    opacity: 0
  }

  84% {
    left: -25px;
    opacity: 1;
    transform: rotate(-45deg)
  }

  96% {
    left: 50px;
    transform: rotate(0deg)
  }
}

@keyframes br {
  0%,96%,100% {
    transform: rotate(0deg)
  }

  12% {
    left: 125px;
    opacity: 1;
    transform: rotate(45deg)
  }

  13%,59% {
    opacity: 0
  }

  60% {
    left: -25px;
    opacity: 1;
    transform: rotate(45deg)
  }

  72% {
    left: 50px;
    transform: rotate(90deg)
  }

  84% {
    transform: rotate(45deg)
  }
}
